func validateMemberType(memberType string) error {
	switch {
	case memberType == "" || strings.EqualFold(memberType, userResource):
		return nil
	case strings.EqualFold(memberType, groupResource):
		return NewError(http.StatusBadRequest, "Nested group members are not supported", "invalidValue")
	default:
		return NewError(http.StatusBadRequest, fmt.Sprintf("Unsupported member type: %s", memberType), "invalidValue")
	}
}

